/**
 * Built-in Color Grading LUTs (v0.4.0).
 *
 * The .cube files live in tools/luts/ (generated by
 * tools/luts/generate_luts.py) and are shipped inside the app
 * bundle (tools/** is in asarUnpack). They are designed for
 * Rec.709 input — never for LOG footage.
 *
 * This module is pure data (no Electron import) so both the
 * renderer (dropdown) and the main process (path resolution)
 * can use it.
 */
export interface BuiltinLut {
  /** File name under tools/luts/ (without .cube). */
  id: string
  /** Vietnamese label shown in the Dashboard panel. */
  label: string
}

export const BUILTIN_LUTS: BuiltinLut[] = [
  { id: 'warm-cinematic', label: 'Ấm điện ảnh' },
  { id: 'colorful', label: 'Đầy màu sắc' },
  { id: 'clean-natural', label: 'Sạch tự nhiên' },
  { id: 'film-fade', label: 'Mờ phim' },
  { id: 'monochrome', label: 'Đơn sắc' },
]

/** The dropdown value for "no LUT" and for a user .cube file. */
export const LUT_NONE = 'none'
export const LUT_CUSTOM = 'custom'

export function isBuiltinLut(id: string): boolean {
  return BUILTIN_LUTS.some((lut) => lut.id === id)
}
